const FlowStepper = ({ steps, activeIndex }) => (
  <Stack direction="row" alignItems="center" sx={{ mb: 3.5 }}>
    {steps.map((label, i) => {
      const done = i < activeIndex;
      const active = i === activeIndex;
      return (
        <React.Fragment key={label}>
          <Stack direction="row" alignItems="center" spacing={1} sx={{ flexShrink: 0 }}>
            <Box
              sx={{
                width: 26,
                height: 26,
                borderRadius: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily: FONT_MONO,
                fontSize: 12,
                fontWeight: 700,
                flexShrink: 0,
                transition: "all 0.2s ease",
                color: done || active ? "#04140F" : MUTED,
                background: done
                  ? `linear-gradient(135deg, ${PRIMARY}, ${PRIMARY2})`
                  : active
                  ? `linear-gradient(135deg, ${GOLD}, ${GOLD2})`
                  : "rgba(16,27,52,0.06)",
              }}
            >
              {done ? <CheckCircle sx={{ fontSize: 15 }} /> : i + 1}
            </Box>
            <Typography
              sx={{
                fontFamily: FONT_UI,
                fontSize: 12.5,
                fontWeight: active ? 700 : 500,
                color: active ? NAVY_TEXT : done ? PRIMARY : MUTED,
                whiteSpace: "nowrap",
                display: { xs: i === activeIndex ? "block" : "none", sm: "block" },
              }}
            >
              {label}
            </Typography>
          </Stack>
          {i !== steps.length - 1 && (
            <Box
              sx={{
                flex: 1,
                height: "1px",
                mx: 1.5,
                minWidth: 16,
                background: i < activeIndex ? PRIMARY : LINE,
                transition: "background 0.2s ease",
              }}
            />
          )}
        </React.Fragment>
      );
    })}
  </Stack>
);

const PageTransition = ({ children, transitionKey }) => (
  <Grow in appear timeout={280} key={transitionKey}>
    <Box>{children}</Box>
  </Grow>
);

/* ------------------------------------------------------------
   Charge breakdown grid — mirrors the "Remitter No / Bank /
   Beneficiary Name / Account Number / Total Amount / Deduction /
   CCF / Commission / TDS" table from the reference screenshot.
   Field names on `chargeDetails` are a best guess (the backend
   response from sendbank3MoneyTransdmt / sendMoneyTrans isn't
   documented here) — rename the keys below to match whatever the
   API actually returns; everything falls back to "—" until then.
   ------------------------------------------------------------ */
const ChargeDetailCell = ({ label, value }) => (
  <Box
    sx={{
      p: 1.5,
      borderRight: `1px solid ${LINE}`,
      borderBottom: `1px solid ${LINE}`,
      minWidth: 0,
    }}
  >
    <Typography sx={{ fontSize: 11, color: MUTED, fontFamily: FONT_UI, fontWeight: 600, mb: 0.4 }}>
      {label}
    </Typography>
    <Typography
      sx={{ fontSize: 13, color: NAVY_TEXT, fontFamily: FONT_MONO, fontWeight: 700 }}
      noWrap
      title={value}
    >
      {value ?? "—"}
    </Typography>
  </Box>
);

const ChargeBreakdown = ({ recipient, bankDisplayName, amount, customer, chargeDetails }) => {
  const rows = [
    ["Remitter No", customer?.mobile],
    ["Bank", bankDisplayName],
    ["Beneficiary Name", recipient?.bank_account_name || recipient?.recipient_name],
    ["Account Number", recipient?.account],
    ["Total Amount", amount ? `INR ${amount}` : "—"],
    [
      "Deduction",
      chargeDetails?.deduction_amount || chargeDetails?.total_deduction
        ? `INR ${chargeDetails?.deduction_amount || chargeDetails?.total_deduction}`
        : "—",
    ],
    [
      "CCF @1.0% (Min. INR 10)",
      chargeDetails?.ccf_amount ? `INR ${chargeDetails.ccf_amount}` : "—",
    ],
    [
      "Commission Amount",
      chargeDetails?.commission_amount ? `INR ${chargeDetails.commission_amount}` : "—",
    ],
    [
      "TDS on Commission",
      chargeDetails?.tds_amount ? `INR ${chargeDetails.tds_amount}` : "—",
    ],
  ];
  const txnCount = chargeDetails?.transaction_count || 1;

  return (
    <Box sx={{ textAlign: "left", mb: 2.5 }}>
      <Box
        sx={{
          borderTop: `1px solid ${LINE}`,
          borderLeft: `1px solid ${LINE}`,
          borderRadius: "10px",
          overflow: "hidden",
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
        }}
      >
        {rows.map(([label, value]) => (
          <ChargeDetailCell key={label} label={label} value={value} />
        ))}
      </Box>
      <Box
        sx={{
          mt: 1,
          p: 1.25,
          borderRadius: "8px",
          border: `1px dashed ${LINE}`,
          backgroundColor: "rgba(148,163,184,0.06)",
        }}
      >
        <Typography sx={{ fontSize: 12, color: MUTED, fontFamily: FONT_UI, fontStyle: "italic" }}>
          This transaction is divided into {txnCount} transaction{txnCount > 1 ? "s" : ""}.
        </Typography>
      </Box>
    </Box>
  );
};

const SendMoneyPopup = ({
  otpResponse,
  setOtpResponse,
  amount,
  transferMode,
  otpSent,
  open,
  onClose,
  recipient,
  chargeDetails,
}) => {
  const {
    setInvoiceId,
    setCurrentPage,
    walletCall,
    setGlobalLoader,
    customer,
    selectedBank,
    allBank,
  } = useBankTransfer();
  const naviagte = useNavigate();
  const [amountError, setAmountError] = useState("");

  const [otp, setOtp] = useState("");
  const [otpError, setOtpError] = useState("");
  const [otpVerified, setOtpVerified] = useState(false);
  const [pin, setPin] = useState("");
  const [pinError, setPinError] = useState("");

  const [otpLoading, setOtpLoading] = useState(false);
  const [moneyLoading, setMoneyLoading] = useState(false);

  // Once the money-transfer call succeeds, swap the dialog body over to
  // the transaction-history view instead of just closing.
  const [transferComplete, setTransferComplete] = useState(false);

  const totalLimit = customer?.total_limit || 0;
  const usedLimit = customer?.used_limit || 0;
  const availableLimit = totalLimit - usedLimit;

  const bankNameObj = allBank.find((item) => item?._id === selectedBank);
  const bankName = bankNameObj?.name || "";

  const validateOtp = (value) => {
    if (!value) return "OTP is required";
    if (!/^\d{6}$/.test(value)) return "OTP must be 6 digits";
    return "";
  };

  const validatePin = (value) => {
    if (!value) return "PIN is required";
    if (!/^\d{4}$/.test(value)) return "PIN must be 4 digits";
    return "";
  };

  const handleSubmitOtp = () => {
    const err = validateOtp(otp);
    setOtpError(err);
    if (!err) {
      setOtpVerified(true);
    }
  };

  const handleSendMoney = withLocation(async (latitude, longitude) => {
    const pinErr = validatePin(pin);
    setPinError(pinErr);
    if (!pinErr) {
      setMoneyLoading(true);
      let body = {
        recipient_id: recipient.recipient_id,
        amount: amount,
        customer_mobile: recipient.recipient_mobile,
        channel: transferMode,
        beneficiary_name:
          recipient?.bank_account_name || recipient?.recipient_name,
        bank_name: recipient.bank,
        ifsc_code: recipient.ifsc,
        account_number: recipient.account,
        customer_name: customer?.name,
        api_id: selectedBank,
        user_id: window.localStorage.getItem("userIdToken"),
        latlong: `${latitude},${longitude}`,
        tpin: pin,
      };
      if (bankName === "bank1") {
        body.otp = otp;
        body.value = otpResponse;
      }
      try {
        const res = await sendMoneyTrans(body);
        toastMessage(res?.data?.error, res?.data?.message);
        if (
          res?.data?.statusCode === "200" ||
          res?.data?.statusCode === "127"
        ) {
          setInvoiceId(res?.data?.data?.[0]?.batchId);
          walletCall();
          // Show the transaction-history view inside this dialog instead
          // of immediately jumping away — the person can still open the
          // full invoice from here.
          setTransferComplete(true);
        }
        if (res?.data?.statusCode === "400") {
          setTimeout(() => {
            onClose();
          }, 400);
        }

        if (res?.data?.statusCode === "405") {
          onClose();
          setOtpResponse("");
          setOtpVerified(false);
          otpSent(false);
        }

        setTimeout(() => {
          setPin("");
        }, 500);
      } catch (error) {
      } finally {
        setMoneyLoading(false);
      }
    }
  });

  const renderStep = () => {
    const showOtpInput = bankName === "bank1" && otpSent && !otpVerified;
    const showPinInput =
      (bankName === "bank1" && otpVerified) ||
      (bankName === "bank2" && otpSent);

    return (
      <>
        {showOtpInput && (
          <>
            <CustomTextField
              fullWidth
              label="Enter OTP"
              placeholder={"Enter 6 Digit Otp"}
              value={otp}
              onChange={(e) => {
                const value = e.target.value;
                if (/^\d{0,6}$/.test(value)) {
                  setOtp(value);
                }
              }}
              inputProps={{ maxLength: 6 }}
              error={!!otpError}
              helperText={otpError}
              size="small"
              className="mt-3"
            />
            <Button
              fullWidth
              variant="contained"
              onClick={handleSubmitOtp}
              sx={{ mt: 2, py: 1.2, ...gradientBtnSx(!otp || otp.length !== 6) }}
              disabled={!otp || otp.length != 6}
            >
              Submit OTP
            </Button>
          </>
        )}

        {showPinInput && (
          <>
            <CustomTextField
              fullWidth
              label="Enter Web T-Pin"
              type="password"
              value={pin}
              onChange={(e) => {
                const value = e.target.value;
                if (/^\d{0,4}$/.test(value)) {
                  setPin(value);
                }
              }}
              inputProps={{ maxLength: 4 }}
              error={!!pinError}
              helperText={pinError}
              size="small"
              className="mt-3"
            />
            <Button
              fullWidth
              variant="contained"
              onClick={handleSendMoney}
              sx={{ mt: 2, py: 1.2, ...gradientBtnSx(pin.length !== 4 || moneyLoading) }}
              disabled={pin.length != 4 || moneyLoading}
            >
              {moneyLoading ? "Sending..." : "Send Money"}
            </Button>
          </>
        )}
      </>
    );
  };

  return (
    <Dialog
      open={open}
      maxWidth="sm"
      fullWidth
      onClose={() => {}}
      disableEscapeKeyDown
      disableBackdropClick
      TransitionComponent={Grow}
      PaperProps={{ onClick: (e) => e.stopPropagation(), sx: { borderRadius: "20px" } }}
    >
      <DialogContent sx={{ textAlign: "center", pt: 4, maxHeight: "75vh", overflowY: "auto" }}>
        {!transferComplete ? (
          <>
            <IconBadge icon={<LockIcon sx={{ color: "#0A0F1C", fontSize: 24 }} />} />
            <Typography
              sx={{ fontWeight: 800, fontFamily: FONT_DISPLAY, fontSize: 19, color: NAVY_TEXT, mb: 0.5 }}
            >
              Send Money
            </Typography>
            <Typography sx={{ color: MUTED, fontFamily: FONT_DISPLAY, fontSize: 13, mb: 2 }}>
              {otpSent && !otpVerified && "Please enter the OTP sent to your number"}
              {otpSent && otpVerified && "Please enter your 4-digit TPIN to confirm"}
            </Typography>

            {otpSent && (
              <ChargeBreakdown
                recipient={recipient}
                bankDisplayName={getBankDisplayName(bankNameObj)?.toUpperCase()}
                amount={amount}
                customer={customer}
                chargeDetails={chargeDetails}
              />
            )}

            <Box mt={1} textAlign="left">
              {renderStep()}
            </Box>
          </>
        ) : (
          <>
            <IconBadge icon={<CheckCircle sx={{ color: "#0A0F1C", fontSize: 24 }} />} />
            <Typography
              sx={{ fontWeight: 800, fontFamily: FONT_DISPLAY, fontSize: 19, color: NAVY_TEXT, mb: 0.5 }}
            >
              Money Sent
            </Typography>
            <Typography sx={{ color: MUTED, fontFamily: FONT_DISPLAY, fontSize: 13, mb: 1 }}>
              ₹{amount} sent to {recipient?.bank_account_name || recipient?.recipient_name}
            </Typography>
            <Box textAlign="left">
              <TransactionHistoryPanel mobile={customer?.mobile} apiId={selectedBank} />
            </Box>
          </>
        )}
      </DialogContent>

      <DialogActions sx={{ justifyContent: "center", pb: 3, gap: 1.5 }}>
        {transferComplete ? (
          <>
            <Button variant="outlined" sx={outlineBtnSx} onClick={onClose}>
              Done
            </Button>
            <Button
              variant="contained"
              sx={gradientBtnSx(false)}
              onClick={() => {
                onClose();
                setCurrentPage("invoice");
              }}
            >
              View Invoice
            </Button>
          </>
        ) : (
          <Button variant="outlined" sx={outlineBtnSx} onClick={onClose}>
            Cancel
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

